public class Variables {
    public static void main(String[] args) {
        int edad = 17;                  // entero
        double precio = 19.95;          // decimal
        char inicial = 'A';             // un carácter
        boolean aprobado = true;        // verdadero o falso
        String nombre = "Lucía";        // texto (clase, no primitivo)
        long poblacion = 8_000_000_000L; // entero grande

        byte nivel = 100;               // de -128 a 127
        short anio = 2025;              // de -32768 a 32767
        float altura = 1.75f;           // decimal de menor precisión
        final double IVA = 0.21;        // constante
        var total = precio * (1 + IVA); // var: el tipo deducido es double

        edad = edad + 1;                // reasignación
        System.out.println(nombre + " (" + inicial + ") tiene " + edad + " años");
        System.out.println("Total con IVA: " + total + ", aprobado: " + aprobado);
        System.out.println("Población: " + poblacion);
        System.out.println(nivel + " " + anio + " " + altura);
    }
}

public class Operadores {
    public static void main(String[] args) {
        int a = 17, b = 5;
        System.out.println(a + b);    // 22
        System.out.println(a / b);    // 3   (división entera)
        System.out.println(a % b);    // 2   (resto)
        System.out.println(17.0 / 5); // 3.4 (división decimal)

        boolean mayor = a > b;              // true
        boolean enRango = a >= 10 && a <= 20; // true
        boolean par = a % 2 == 0;           // false
        System.out.println(mayor + " " + enRango + " " + !par);

        int x = 10;
        x += 5;   // 15
        x *= 2;   // 30
        x++;      // 31
        System.out.println("x = " + x);

        int y = 3 + 4 * 2;      // 11: * antes que +
        int z = (3 + 4) * 2;    // 14
        System.out.println(y + " " + z);
    }
}

public class Conversiones {
    public static void main(String[] args) {
        int entero = 7;
        double decimal = entero;          // automática: 7.0
        int truncado = (int) 9.99;        // casting: 9
        long redondeado = Math.round(9.5); // redondeo: 10

        System.out.println(decimal + " " + truncado + " " + redondeado);

        // Cuidado: la división entera ocurre antes de convertir
        double malo = 7 / 2;              // 3.0
        double bueno = (double) 7 / 2;    // 3.5
        System.out.println(malo + " " + bueno);

        // Texto <-> número
        int edad = Integer.parseInt("42");
        double precio = Double.parseDouble("19.95");
        String texto = String.valueOf(edad + 1);
        System.out.println(texto + " " + (precio * 2));

        // char <-> int
        System.out.println((int) 'A');   // 65
        System.out.println((char) 66);   // B
        // Envoltorios: Integer frente a int
        Integer envuelto = 5;             // autoboxing: int -> Integer
        int primitivo = envuelto + 1;     // unboxing: Integer -> int
        System.out.println(Integer.MAX_VALUE + " " + primitivo);
        System.out.println((byte) 200);   // -56: no cabe en un byte
    }
}

