public class EjemploSwitch {
    public static void main(String[] args) {
        int dia = 6;

        // Sintaxis de flecha
        switch (dia) {
            case 1, 2, 3, 4, 5 -> System.out.println("Laborable");
            case 6, 7 -> System.out.println("Fin de semana");
            default -> System.out.println("Día no válido");
        }

        // Expresión switch: devuelve un valor
        String operador = "*";
        int resultado = switch (operador) {
            case "+" -> 4 + 2;
            case "-" -> 4 - 2;
            case "*" -> 4 * 2;
            case "/" -> {
                System.out.println("Dividiendo...");
                yield 4 / 2;
            }
            default -> 0;
        };
        System.out.println("Resultado: " + resultado);

        // Sintaxis clásica: ¡no olvides el break!
        char letra = 'b';
        switch (letra) {
            case 'a':
                System.out.println("Opción A");
                break;
            case 'b':
                System.out.println("Opción B");
                break;
            default:
                System.out.println("Otra opción");
        }
    }
}

public class Bucles {
    public static void main(String[] args) {
        // Del 1 al 5
        for (int i = 1; i <= 5; i++) {
            System.out.print(i + " ");
        }
        System.out.println();

        // Cuenta atrás de 2 en 2
        for (int i = 10; i > 0; i -= 2) {
            System.out.print(i + " ");
        }
        System.out.println();

        // Acumular: suma de 1 a 100
        int suma = 0;
        for (int i = 1; i <= 100; i++) {
            suma += i;
        }
        System.out.println("Suma: " + suma);

        // Recorrer un array con índice y con for-each
        int[] notas = {7, 4, 9, 6};
        for (int i = 0; i < notas.length; i++) {
            System.out.println("Nota " + i + ": " + notas[i]);
        }
        for (int nota : notas) {
            System.out.print(nota + " ");
        }
        System.out.println();
    }
}

import java.util.Scanner;

public class Mientras {
    public static void main(String[] args) {
        // while: ¿cuántas veces se puede dividir entre 2?
        int n = 100;
        int pasos = 0;
        while (n > 1) {
            n /= 2;
            pasos++;
        }
        System.out.println("Pasos: " + pasos);

        // do-while: pedir un número hasta que sea válido
        Scanner sc = new Scanner(System.in);
        int edad;
        do {
            System.out.print("Edad (0-120): ");
            edad = sc.nextInt();
        } while (edad < 0 || edad > 120);
        System.out.println("Edad válida: " + edad);
    }
}

public class SaltosEnBucles {
    public static void main(String[] args) {
        // break: buscar el primer múltiplo de 7 mayor que 50
        for (int i = 51; i < 100; i++) {
            if (i % 7 == 0) {
                System.out.println("Encontrado: " + i);
                break;
            }
        }

        // continue: imprimir solo los impares
        for (int i = 1; i <= 10; i++) {
            if (i % 2 == 0) {
                continue;
            }
            System.out.print(i + " ");
        }
        System.out.println();

        // break con etiqueta: salir de dos bucles a la vez
        externo:
        for (int fila = 0; fila < 5; fila++) {
            for (int col = 0; col < 5; col++) {
                if (fila * col == 6) {
                    System.out.println("Parada en " + fila + "," + col);
                    break externo;
                }
            }
        }
    }
}

