import java.time.Duration;
import java.util.concurrent.TimeUnit;

public class Esperar {
    public static void main(String[] args) throws InterruptedException {
        // Cuenta atrás de un segundo en un segundo
        for (int i = 3; i > 0; i--) {
            System.out.println(i + "...");
            Thread.sleep(1000);
        }
        System.out.println("¡Despegue!");

        TimeUnit.MILLISECONDS.sleep(500);
        Thread.sleep(Duration.ofMillis(250));

        // Medir el tiempo transcurrido
        long inicio = System.currentTimeMillis();
        esperarSinThrows(300);
        long fin = System.currentTimeMillis();
        System.out.println("Han pasado " + (fin - inicio) + " ms");
    }

    // Variante capturando la excepción en lugar de declararla
    static void esperarSinThrows(long ms) {
        try {
            Thread.sleep(ms);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}

public class Textos {
    public static void main(String[] args) {
        String s = "  Programación en Java  ";
        String limpio = s.strip();

        System.out.println(limpio.length());          // 20
        System.out.println(limpio.charAt(0));         // P
        System.out.println(limpio.substring(0, 12));  // Programación
        System.out.println(limpio.indexOf("Java"));   // 16
        System.out.println(limpio.toUpperCase());
        System.out.println(limpio.replace("Java", "Python"));

        // Comparar: equals, no ==
        String a = "hola";
        String b = new String("hola");
        System.out.println(a == b);                   // false
        System.out.println(a.equals(b));              // true
        System.out.println("HOLA".equalsIgnoreCase(a)); // true

        // Recorrer carácter a carácter: contar vocales
        int vocales = 0;
        for (int i = 0; i < limpio.length(); i++) {
            char c = Character.toLowerCase(limpio.charAt(i));
            if ("aeiouáéíóú".indexOf(c) >= 0) {
                vocales++;
            }
        }
        System.out.println("Vocales: " + vocales);

        // Trocear y construir
        String[] partes = "rojo,verde,azul".split(",");
        StringBuilder sb = new StringBuilder();
        for (String p : partes) {
            sb.append(p.toUpperCase()).append(' ');
        }
        System.out.println(sb.toString().strip());
        // compareTo, format y secuencias de escape
        System.out.println("ana".compareTo("luis") < 0);   // true: "ana" va antes
        String ficha = String.format("%s tiene %d años", "Pepito", 25);
        System.out.println(ficha + "\tTab y \"comillas\"");
        System.out.println("-".repeat(10));
    }
}

import java.util.Random;

public class Matematicas {
    public static void main(String[] args) {
        System.out.println(Math.abs(-7));        // 7
        System.out.println(Math.max(4, 9));      // 9
        System.out.println(Math.pow(2, 10));     // 1024.0
        System.out.println(Math.sqrt(81));       // 9.0

        System.out.println(Math.round(2.5));     // 3
        System.out.println(Math.floor(2.7));     // 2.0
        System.out.println(Math.ceil(2.1));      // 3.0

        double radio = 3;
        double area = Math.PI * Math.pow(radio, 2);
        System.out.printf("Área: %.2f%n", area);

        // Dado de 6 caras con Math.random
        int dado = (int) (Math.random() * 6) + 1;
        System.out.println("Dado: " + dado);

        // Con Random: entero entre 1 y 100 (100 incluido)
        Random r = new Random();
        System.out.println("Aleatorio: " + r.nextInt(1, 101));

        // Trigonometría: los ángulos van en radianes
        double angulo = Math.toRadians(30);
        System.out.printf("sen(30º) = %.2f%n", Math.sin(angulo));   // 0.50
        // Hipotenusa de un triángulo rectángulo
        System.out.println(Math.hypot(3, 4));    // 5.0
    }
}

public class Funciones {
    public static void main(String[] args) {
        saludar("Marta");
        int total = sumar(4, 7);
        System.out.println("Suma: " + total);
        System.out.println("¿17 es primo? " + esPrimo(17));
        System.out.println("Media: " + media(6, 8));
        System.out.println("Media: " + media(6, 8, 10));
    }

    // Sin valor de retorno
    static void saludar(String nombre) {
        System.out.println("Hola, " + nombre);
    }

    // Devuelve un int
    static int sumar(int a, int b) {
        return a + b;
    }

    // Devuelve un boolean; return termina en cuanto se conoce la respuesta
    static boolean esPrimo(int n) {
        if (n < 2) {
            return false;
        }
        for (int i = 2; i * i <= n; i++) {
            if (n % i == 0) {
                return false;
            }
        }
        return true;
    }

    // Sobrecarga: mismo nombre, distintos parámetros
    static double media(double a, double b) {
        return (a + b) / 2;
    }

    static double media(double a, double b, double c) {
        return (a + b + c) / 3;
    }
}

public class Ambito {
    static int contador = 0; // variable de clase: visible en todos los métodos static

    public static void main(String[] args) {
        int x = 10; // local de main

        if (x > 5) {
            int y = x * 2; // solo existe dentro de este if
            System.out.println("y = " + y);
        }
        // System.out.println(y); // ERROR: y no existe aquí

        for (int i = 0; i < 3; i++) {
            incrementar();
        }
        // System.out.println(i); // ERROR: i solo existe en el for

        System.out.println("contador = " + contador); // 3
        ocultar();
    }

    static void incrementar() {
        contador++; // accede a la variable de clase
        // x++;     // ERROR: x es local de main
    }

    static void ocultar() {
        int contador = 100; // oculta a la variable de clase
        System.out.println("local: " + contador);           // 100
        System.out.println("de clase: " + Ambito.contador); // 3
    }
}

import java.util.Arrays;

public class Parametros {
    public static void main(String[] args) {
        // Primitivo: el original no cambia
        int n = 5;
        duplicar(n);
        System.out.println("n = " + n); // 5

        // Array: el método modifica el contenido
        int[] datos = {1, 2, 3};
        duplicarTodos(datos);
        System.out.println(Arrays.toString(datos)); // [2, 4, 6]

        // Varargs: cualquier número de argumentos
        System.out.println(sumar());           // 0
        System.out.println(sumar(4));          // 4
        System.out.println(sumar(1, 2, 3, 4)); // 10

        // Varios parámetros de distinto tipo
        mostrar("Total", 12.5, true);
    }

    static void duplicar(int x) {
        x = x * 2; // modifica solo la copia
    }

    static void duplicarTodos(int[] v) {
        for (int i = 0; i < v.length; i++) {
            v[i] *= 2;
        }
    }

    static int sumar(int... numeros) {
        int total = 0;
        for (int num : numeros) {
            total += num;
        }
        return total;
    }

    static void mostrar(String etiqueta, double valor, boolean destacado) {
        String marca = destacado ? " ***" : "";
        System.out.println(etiqueta + ": " + valor + marca);
    }
}

