import java.util.Scanner;

public class Excepciones {
    public static void main(String[] args) {
        // Capturar un error concreto
        try {
            int n = Integer.parseInt("doce");
            System.out.println(n);
        } catch (NumberFormatException e) {
            System.out.println("No es un número: " + e.getMessage());
        }

        // Varios catch y finally
        int[] v = {1, 2, 3};
        try {
            System.out.println(v[5] / 0);
        } catch (ArithmeticException e) {
            System.out.println("División entre cero");
        } catch (ArrayIndexOutOfBoundsException e) {
            System.out.println("Índice fuera del array");
        } finally {
            System.out.println("Esto se ejecuta siempre");
        }

        // Lanzar y capturar una excepción propia
        try {
            System.out.println(dividir(10, 0));
        } catch (IllegalArgumentException e) {
            System.out.println("Error: " + e.getMessage());
        }

        // try-with-resources: el Scanner se cierra solo
        try (Scanner sc = new Scanner("15 abc")) {
            int edad = sc.nextInt();
            System.out.println("Leído: " + edad);
        }
    }

    static int dividir(int a, int b) {
        if (b == 0) {
            throw new IllegalArgumentException("el divisor no puede ser 0");
        }
        return a / b;
    }
}

import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Regex {
    public static void main(String[] args) {
        // Validar formatos
        String dni = "12345678Z";
        System.out.println(dni.matches("\\d{8}[A-Z]"));            // true

        String cp = "4800";
        System.out.println(cp.matches("\\d{5}"));                  // false

        String correo = "ana.lopez@instituto.es";
        System.out.println(correo.matches("[\\w.]+@[\\w]+\\.[a-z]{2,}")); // true

        // Reemplazar y trocear
        String texto = "Hay   demasiados    espacios";
        System.out.println(texto.replaceAll("\\s+", " "));
        String[] palabras = "uno, dos;tres  cuatro".split("[,;\\s]+");
        System.out.println(palabras.length);                       // 4

        // Buscar todas las coincidencias y extraer grupos
        Pattern p = Pattern.compile("(\\d{2})/(\\d{2})/(\\d{4})");
        Matcher m = p.matcher("Exámenes: 12/01/2026 y 03/06/2026");
        while (m.find()) {
            System.out.println("Día " + m.group(1) + ", mes " + m.group(2)
                    + ", año " + m.group(3));
        }
        // Flags: matrícula española sin distinguir mayúsculas
        Pattern matricula = Pattern.compile("^\\d{4}[BCDFGHJKLMNPRSTVWXYZ]{3}$", Pattern.CASE_INSENSITIVE);
        System.out.println(matricula.matcher("1234bcd").matches());   // true
    }
}

