import java.util.Arrays;

public class Matrices {
    public static void main(String[] args) {
        // 24 filas (horas) x 60 columnas (minutos)
        int[][] velViento = new int[24][60];
        velViento[13][30] = 25; // a las 13:30

        // Inicialización directa de una matriz 2x3
        int[][] m = {
            {10, 11, 12},
            {13, 14, 15}
        };

        System.out.println("Filas: " + m.length);           // 2
        System.out.println("Columnas: " + m[0].length);     // 3
        System.out.println("Elemento [1][2]: " + m[1][2]);  // 15

        // Recorrer con doble bucle: i recorre filas, j columnas
        for (int i = 0; i < m.length; i++) {
            for (int j = 0; j < m[i].length; j++) {
                System.out.print(m[i][j] + "\t");
            }
            System.out.println();
        }

        // Tres dimensiones: 2 bloques de 3 filas y 4 columnas
        int[][][] cubo = new int[2][3][4];
        cubo[1][2][3] = 7;
        System.out.println(cubo.length + "x" + cubo[0].length + "x" + cubo[0][0].length);

        // Filas de distinto tamaño (array irregular)
        int[][] triangulo = new int[3][];
        for (int i = 0; i < triangulo.length; i++) {
            triangulo[i] = new int[i + 1];
        }
        System.out.println(Arrays.deepToString(triangulo));  // [[0], [0, 0], [0, 0, 0]]
    }
}

public class RecorrerArrays {
    public static void main(String[] args) {
        int[] numeros = new int[5];

        // for con índice: necesario para escribir en el array
        for (int i = 0; i < numeros.length; i++) {
            numeros[i] = (i + 1) * 10;
        }

        // for-each: para leer todos los elementos sin índice
        int suma = 0;
        for (int n : numeros) {
            suma += n;
        }
        System.out.println("Suma: " + suma);

        // Cuidado: asignar a la variable del for-each no cambia el array
        for (int n : numeros) {
            n = 0; // solo cambia la copia
        }
        System.out.println("numeros[0] sigue valiendo " + numeros[0]);

        // Recorrer una matriz con for-each anidado
        int[][] matriz = {{1, 2, 3}, {4, 5, 6}};
        for (int[] fila : matriz) {
            for (int valor : fila) {
                System.out.print(valor + " ");
            }
            System.out.println();
        }

        // Recorrer al revés (solo con índice)
        for (int i = numeros.length - 1; i >= 0; i--) {
            System.out.print(numeros[i] + " ");
        }
        System.out.println();
    }
}

import java.util.Arrays;

public class BuscarEnArrays {
    public static void main(String[] args) {
        int[] datos = {42, 7, 19, 3, 88, 19};

        // Búsqueda lineal: recorrer y comparar
        int buscado = 19;
        int posicion = -1;
        for (int i = 0; i < datos.length; i++) {
            if (datos[i] == buscado) {
                posicion = i;
                break; // nos quedamos con la primera aparición
            }
        }
        System.out.println("Lineal: " + buscado + " está en la posición " + posicion);

        // En un array de String se compara con equals
        String[] nombres = {"Ana", "Luis", "Marta"};
        boolean encontrado = false;
        for (String n : nombres) {
            if (n.equals("Luis")) {
                encontrado = true;
            }
        }
        System.out.println("¿Está Luis? " + encontrado);

        // Búsqueda binaria: el array DEBE estar ordenado
        int[] ordenado = Arrays.copyOf(datos, datos.length);
        Arrays.sort(ordenado);                                  // [3, 7, 19, 19, 42, 88]
        System.out.println(Arrays.binarySearch(ordenado, 42));  // 4
        System.out.println(Arrays.binarySearch(ordenado, 50));  // negativo: no está

        // Copiar frente a referenciar
        int[] mismo = datos;                              // misma referencia
        int[] copia = Arrays.copyOf(datos, datos.length); // copia independiente
        datos[0] = 0;
        System.out.println(mismo[0] + " " + copia[0]);    // 0 42
        System.out.println(Arrays.equals(datos, mismo));  // true
    }
}

import java.util.Arrays;
import java.util.Collections;

public class Ordenar {
    public static void main(String[] args) {
        int[] numeros = {29, 4, 71, 15, 8, 42};
        int[] copia = Arrays.copyOf(numeros, numeros.length);

        // Con la clase Arrays (ascendente)
        Arrays.sort(copia);
        System.out.println(Arrays.toString(copia));

        // Solo un tramo: posiciones de la 1 a la 3 (la 4 no se incluye)
        int[] parcial = {9, 8, 7, 6, 5};
        Arrays.sort(parcial, 1, 4);
        System.out.println(Arrays.toString(parcial));      // [9, 6, 7, 8, 5]

        // Textos: las mayúsculas van antes que las minúsculas
        String[] palabras = {"pera", "Manzana", "kiwi", "Uva"};
        Arrays.sort(palabras);
        System.out.println(Arrays.toString(palabras));     // [Manzana, Uva, kiwi, pera]
        Arrays.sort(palabras, String.CASE_INSENSITIVE_ORDER);
        System.out.println(Arrays.toString(palabras));     // [kiwi, Manzana, pera, Uva]

        // Descendente: necesita objetos (Integer), no primitivos
        Integer[] objetos = {29, 4, 71, 15};
        Arrays.sort(objetos, Collections.reverseOrder());
        System.out.println(Arrays.toString(objetos));

        // Algoritmo propio
        burbuja(numeros);
        System.out.println(Arrays.toString(numeros));
    }

    // Método de la burbuja: en cada pasada el mayor "sube" al final
    static void burbuja(int[] v) {
        for (int pasada = 0; pasada < v.length - 1; pasada++) {
            boolean cambios = false;
            for (int i = 0; i < v.length - 1 - pasada; i++) {
                if (v[i] > v[i + 1]) {
                    int aux = v[i];      // intercambio con variable auxiliar
                    v[i] = v[i + 1];
                    v[i + 1] = aux;
                    cambios = true;
                }
            }
            if (!cambios) {
                break; // si no hubo intercambios, ya está ordenado
            }
        }
    }
}

