public class ClasesEInstancias {
    public static void main(String[] args) {
        // Dos instancias de la misma clase: cada una con su propio estado
        Tortuga t1 = new Tortuga("Leonardo", 3);
        Tortuga t2 = new Tortuga("Rafael", 5);
        t1.avanzar(4);
        t2.avanzar(1);
        System.out.println(t1.describir());
        System.out.println(t2.describir());

        // Dos variables que apuntan al MISMO objeto
        Tortuga t3 = t1;
        t3.avanzar(10);
        System.out.println(t1.describir()); // t1 también ha avanzado
        System.out.println(t1 == t3);       // true: misma referencia
        System.out.println(t1 == t2);       // false

        // Una referencia puede no apuntar a ningún objeto
        Tortuga t4 = null;
        // t4.avanzar(1); // ERROR en ejecución: NullPointerException
        System.out.println(t4 == null);
    }
}

