// Del dado solo modelamos lo que importa: sus caras y tirarlo
class Dado {
    private final int caras;
    private final Random random = new Random();

    Dado(int caras) {
        if (caras < 2 || caras > 100) {
            throw new IllegalArgumentException("Un dado debe tener entre 2 y 100 caras");
        }
        this.caras = caras;
    }

    int tirar() {
        return random.nextInt(1, caras + 1);
    }
}

class Personaje {
    private final String nombre;
    private int vida;

    Personaje(String nombre, int vida) {
        this.nombre = nombre;
        this.vida = vida;
    }

    void atacar(Personaje rival, Dado dado) {
        int danio = dado.tirar() / 4;
        rival.recibir(danio);
        System.out.println(nombre + " golpea a " + rival.nombre + " (" + danio + ")");
    }

    void recibir(int danio) {
        vida = Math.max(0, vida - danio);
    }

    boolean estaVivo() {
        return vida > 0;
    }

    String getNombre() {
        return nombre;
    }
}

