public class Sobrecarga {
    public static void main(String[] args) {
        System.out.println(Operaciones.sumar(2, 3));       // versión int
        System.out.println(Operaciones.sumar(2.5, 3.1));   // versión double
        System.out.println(Operaciones.sumar(1, 2, 3));    // tres parámetros

        Baraja completa = new Baraja();     // 40 cartas
        Baraja corta = new Baraja(10);      // 10 cartas
        corta.barajar();
        System.out.println(completa.tamanio() + " / " + corta);
    }
