class Operaciones {
    static int sumar(int a, int b) { return a + b; }
    static double sumar(double a, double b) { return a + b; }
    static int sumar(int a, int b, int c) { return a + b + c; }
    // static double sumar(int a, int b) { ... } // ERROR: solo cambia el tipo de retorno
}

class Baraja {
    private final int[] cartas;

    Baraja() {
        this(40); // llama al otro constructor
    }

    Baraja(int numCartas) {
        cartas = new int[numCartas];
        for (int i = 0; i < numCartas; i++) {
            cartas[i] = i + 1;
        }
    }

    // Algoritmo de Fisher-Yates
    void barajar() {
        Random r = new Random();
        for (int i = cartas.length - 1; i > 0; i--) {
            int j = r.nextInt(i + 1);
            int aux = cartas[i];
            cartas[i] = cartas[j];
            cartas[j] = aux;
        }
    }

    int tamanio() {
        return cartas.length;
    }

    @Override
    public String toString() {
        return Arrays.toString(cartas);
    }
}

