public class PasoPorValor {
    public static void main(String[] args) {
        int n = 5;
        cambiarPrimitivo(n);
        System.out.println(n);              // 5

        Caja caja = new Caja(5);
        cambiarContenido(caja);
        System.out.println(caja.valor);     // 99: el método modificó el objeto
        cambiarReferencia(caja);
        System.out.println(caja.valor);     // 99: reasignar el parámetro no afecta

        // Copiar un objeto: crear uno nuevo
        Caja copia = new Caja(caja.valor);
        copia.valor = 1;
        System.out.println(caja.valor + " " + copia.valor); // 99 1

        // String es inmutable: sus métodos devuelven otro String
        String s = "hola";
        s.toUpperCase();
        System.out.println(s);              // hola
        s = s.toUpperCase();
        System.out.println(s);              // HOLA

        // Clase inmutable con record
        Punto p = new Punto(1, 2);
        Punto q = p.mover(3, 0);
        System.out.println(p + " -> " + q); // Punto[x=1, y=2] -> Punto[x=4, y=2]
    }

    static void cambiarPrimitivo(int x) { x = 100; }
    static void cambiarContenido(Caja c) { c.valor = 99; }
    static void cambiarReferencia(Caja c) { c = new Caja(-1); }
}

class Caja {
    int valor;
    Caja(int valor) { this.valor = valor; }
}

// record: atributos private final, constructor, getters, equals, hashCode y toString automáticos
record Punto(int x, int y) {
    Punto mover(int dx, int dy) {
        return new Punto(x + dx, y + dy); // no se modifica: se devuelve uno nuevo
    }
}

