import java.util.Objects;

public class ClaseObject {
    public static void main(String[] args) {
        // Una clase vacía ya tiene métodos: los hereda de Object
        Vacia v = new Vacia();
        System.out.println(v.toString());    // Vacia@... (nombre@hash)
        System.out.println(v.getClass().getSimpleName());

        Libro a = new Libro("978-84-1", "Rayuela");
        Libro b = new Libro("978-84-1", "Rayuela");
        System.out.println(a == b);          // false: objetos distintos
        System.out.println(a.equals(b));     // true: mismo ISBN
        System.out.println(a.hashCode() == b.hashCode()); // true
        System.out.println(a);               // usa toString()
    }
}

class Vacia { }

class Libro {
    private final String isbn;
    private final String titulo;

    Libro(String isbn, String titulo) {
        this.isbn = isbn;
        this.titulo = titulo;
    }

    // Dos libros son iguales si tienen el mismo ISBN
    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof Libro otro)) return false;
        return isbn.equals(otro.isbn);
    }

    // Si dos objetos son equals, deben tener el mismo hashCode
    @Override
    public int hashCode() {
        return Objects.hash(isbn);
    }

    @Override
    public String toString() {
        return titulo + " (" + isbn + ")";
    }
}

