        List<Figura> figuras = List.of(new Circulo(1), new Rectangulo(2, 3), new Circulo(2));
        for (Figura f : figuras) {
            // Se ejecuta el area() del objeto real, no el de Figura
            System.out.printf("%s: %.2f%n", f.nombre(), f.area());
        }

        // Todo cabe en un Object
        Object[] cosas = {"texto", 42, new Circulo(3), 3.5};
        for (Object o : cosas) {
            if (o instanceof Circulo c) {          // comprueba y convierte a la vez
                System.out.println("Círculo de radio " + c.radio);
            } else if (o instanceof String s) {
                System.out.println("String de " + s.length() + " letras");
            } else {
                System.out.println("Otro: " + o.getClass().getSimpleName());
            }
        }

        // Casting clásico
        Figura f = new Rectangulo(1, 1);
        if (f instanceof Rectangulo) {
            Rectangulo r = (Rectangulo) f;
            System.out.println("Base: " + r.base);
        }
        // Circulo mal = (Circulo) f; // ClassCastException en ejecución
    }
}

class Figura {
