public class Interfaces {
    public static void main(String[] args) {
        // Referencias de tipo interfaz a clases distintas
        Sonoro[] cosas = {new Pato(), new Timbre()};
        for (Sonoro s : cosas) {
            s.sonar();
            s.sonarVeces(2);              // método default
        }
        System.out.println("Volumen máximo: " + Sonoro.VOLUMEN_MAX); // constante
        System.out.println(Sonoro.describir(new Timbre()));          // método static

        // Una clase que implementa varias interfaces
        Pato p = new Pato();
        p.volar();
        Nadador n = p;   // el mismo objeto visto como Nadador
        n.nadar();
    }
}

interface Sonoro {
    int VOLUMEN_MAX = 10;              // implícitamente public static final

    void sonar();                      // implícitamente public abstract

    default void sonarVeces(int veces) {
        for (int i = 0; i < veces; i++) {
            sonar();
        }
    }

    static String describir(Sonoro s) {
        return "Objeto sonoro: " + s.getClass().getSimpleName();
    }
}

