/* Salida:
Exception in thread "main" java.lang.ArithmeticException: / by zero
    at ErroresYExcepciones.dividirPorCero(ErroresYExcepciones.java:20)   <- dónde ocurrió
    at ErroresYExcepciones.cosa2(ErroresYExcepciones.java:18)
    at ErroresYExcepciones.cosa1(ErroresYExcepciones.java:17)
    at ErroresYExcepciones.main(ErroresYExcepciones.java:14)             <- origen de la llamada
*/

public class CapturaExcepciones {
    public static void main(String[] args) {
        System.out.println(dividir(10, 2));
        System.out.println(dividir(10, 0));

        // Varios catch: del más específico al más general
        String[] datos = {"8", "x"};
        for (int i = 0; i <= datos.length; i++) {   // el último índice no existe
            try {
                int n = Integer.parseInt(datos[i]);
                System.out.println("Número: " + n);
            } catch (NumberFormatException e) {
                System.out.println("No es un número: " + e.getMessage());
            } catch (ArrayIndexOutOfBoundsException e) {
                System.out.println("Fuera del array: " + e.getMessage());
            } catch (Exception e) {
                System.out.println("Otro error: " + e);
            }
        }
    }

    static int dividir(int a, int b) {
        try {
            System.out.println("Intentando " + a + " / " + b);
            return a / b;
        } catch (ArithmeticException e) {
            System.out.println("Error: " + e.getMessage());
            return 0;                        // finally se ejecuta igualmente
        } finally {
            System.out.println("finally: siempre se ejecuta, incluso tras un return");
        }
    }
}

import java.io.IOException;

public class PropagarExcepciones {
    public static void main(String[] args) {
        try {
            procesar(-5);
        } catch (IllegalArgumentException e) {
            System.out.println("Capturada en main: " + e.getMessage());
        }

        try {
            leerConfiguracion("config.txt");
        } catch (IOException e) {
            System.out.println("No se pudo leer: " + e.getMessage());
        }
    }

    // La excepción atraviesa procesar() hasta main sin que procesar la trate
    static void procesar(int edad) {
        validarEdad(edad);
        System.out.println("Edad válida");
    }

    // throw: lanza una excepción en este punto
    static void validarEdad(int edad) {
        if (edad < 0) {
            throw new IllegalArgumentException("La edad no puede ser negativa: " + edad);
        }
    }

    // throws: avisa de que el método puede lanzar una excepción comprobada
    // y obliga a quien lo llama a capturarla o a declararla también
    static void leerConfiguracion(String ruta) throws IOException {
        throw new IOException("el fichero " + ruta + " no existe");
    }
}

public class ExcepcionesPersonalizadas {
    public static void main(String[] args) {
        Cuenta c = new Cuenta(100);
        try {
            c.retirar(30);
            c.retirar(200);
        } catch (SaldoInsuficienteException e) {
            System.out.println(e.getMessage());
            System.out.println("Faltan " + e.getFaltante() + " €");
        }
    }
