// Comprobada: hereda de Exception, obliga a capturarla o declararla
class SaldoInsuficienteException extends Exception {
    private final double faltante;

    SaldoInsuficienteException(String mensaje, double faltante) {
        super(mensaje);
        this.faltante = faltante;
    }

    double getFaltante() {
        return faltante;
    }
}

class Cuenta {
    private double saldo;

    Cuenta(double saldo) {
        this.saldo = saldo;
    }

    void retirar(double cantidad) throws SaldoInsuficienteException {
        if (cantidad > saldo) {
            throw new SaldoInsuficienteException("Saldo insuficiente para retirar " + cantidad + " €", cantidad - saldo);
        }
        saldo -= cantidad;
        System.out.println("Retirados " + cantidad + " €. Saldo: " + saldo);
    }
}

import java.util.*;

public class Colecciones {
    public static void main(String[] args) {
        // List: orden de inserción, admite duplicados, acceso por índice
        List<String> lista = new ArrayList<>();
        lista.add("pera");
        lista.add("manzana");
        lista.add("pera");
        System.out.println("List: " + lista + " -> " + lista.get(1));

        // Set: sin duplicados
        Set<String> hash = new HashSet<>(lista);           // sin orden garantizado
        Set<String> enlazado = new LinkedHashSet<>(lista); // orden de inserción
        Set<String> arbol = new TreeSet<>(lista);          // ordenado
        System.out.println("Set: " + hash + " " + enlazado + " " + arbol);

        // Map: pares clave -> valor
        Map<String, Integer> stock = new HashMap<>();
        stock.put("pera", 12);
        stock.put("kiwi", 4);
        stock.put("pera", 15);                 // la clave ya existía: se sustituye
        System.out.println("Map: " + stock + " -> pera = " + stock.get("pera"));

        // Queue: primero en entrar, primero en salir
        Queue<String> cola = new LinkedList<>();
        cola.offer("cliente 1");
        cola.offer("cliente 2");
        System.out.println("Queue: atiende a " + cola.poll() + ", quedan " + cola);

        // Pila (último en entrar, primero en salir): mejor ArrayDeque que Stack
        Deque<Integer> pila = new ArrayDeque<>();
        pila.push(1);
        pila.push(2);
        pila.push(3);
        System.out.println("Pila: saca " + pila.pop() + ", quedan " + pila);

        // Utilidades de la clase Collections
        Collections.sort(lista);
        System.out.println("Ordenada: " + lista + ", máximo " + Collections.max(lista));

        // Colección inmutable
        List<Integer> fija = List.of(1, 2, 3);
        // fija.add(4); // UnsupportedOperationException
        System.out.println(fija);
    }
}

