public class Genericos {
    public static void main(String[] args) {
        // Una sola clase genérica en lugar de InfoString, InfoInteger, InfoBoolean...
        Info<String> texto = new Info<>("hola");
        Info<Integer> numero = new Info<>(42);
        String s = texto.getDato();     // sin casting
        int n = numero.getDato();
        System.out.println(s + " " + n);

        // Método genérico
        imprimirDosVeces("eco");
