        // Tipo acotado: solo admite Animal o sus subclases
        Cuidador<Perro> cuidador = new Cuidador<>(new Perro("Toby"));
        cuidador.cuidar();

        // Comodín: acepta listas de Animal o de cualquier subclase
        List<Perro> perros = List.of(new Perro("Rex"), new Perro("Lua"));
        List<Gato> gatos = List.of(new Gato("Misi"));
