import java.util.*;

public class QueColeccionUsar {
    public static void main(String[] args) {
        // Historial de pedidos en orden, con repetidos -> List
        List<String> pedidos = new ArrayList<>(List.of("café", "té", "café"));

        // Ingredientes distintos, en orden alfabético -> TreeSet
        Set<String> ingredientes = new TreeSet<>(List.of("leche", "azúcar", "leche", "canela"));

        // Precio de cada producto -> Map
        Map<String, Double> precios = new HashMap<>();
        precios.put("café", 1.20);
        precios.put("té", 1.10);

        // Clientes esperando turno -> Queue (FIFO)
        Queue<String> turno = new ArrayDeque<>(List.of("Ana", "Luis"));

        // Deshacer acciones -> pila (LIFO) con Deque
        Deque<String> deshacer = new ArrayDeque<>();
        deshacer.push("escribir");
        deshacer.push("borrar");

        // Tareas por urgencia -> PriorityQueue (sale primero el menor)
        Queue<Integer> urgencias = new PriorityQueue<>(List.of(3, 1, 2));

        System.out.println(pedidos + " " + ingredientes + " " + precios.get("café"));
        System.out.println(turno.poll() + " " + deshacer.pop() + " " + urgencias.poll()); // Ana borrar 1
    }
}

import java.util.*;

public class ListEIterator {
    public static void main(String[] args) {
        List<Integer> numeros = new ArrayList<>(List.of(4, 7, 10, 13, 16));

        // Iterator básico
        Iterator<Integer> it = numeros.iterator();
        while (it.hasNext()) {
            int n = it.next();
            System.out.print(n + " ");
        }
        System.out.println();

        // Eliminar mientras se recorre: SOLO con it.remove()
        it = numeros.iterator();
        while (it.hasNext()) {
            if (it.next() % 2 != 0) {
                it.remove();
            }
        }
        System.out.println(numeros);   // [4, 10, 16]

        // Esto lanzaría ConcurrentModificationException:
        // for (Integer n : numeros) { numeros.remove(n); }

        // Alternativa moderna
        numeros.removeIf(n -> n > 12);
        System.out.println(numeros);   // [4, 10]

        // ListIterator: recorre en ambos sentidos y permite modificar
        List<String> nombres = new LinkedList<>(List.of("ana", "luis", "marta"));
        ListIterator<String> li = nombres.listIterator();
        while (li.hasNext()) {
            li.set(li.next().toUpperCase());
        }
        while (li.hasPrevious()) {
            System.out.print(li.previous() + " ");   // MARTA LUIS ANA
        }
        System.out.println();
    }
}

import java.util.*;

public class EjemploSet {
    public static void main(String[] args) {
        Set<String> colores = new HashSet<>();
        System.out.println(colores.add("rojo"));   // true
        System.out.println(colores.add("rojo"));   // false: ya estaba
        colores.add("azul");
        System.out.println(colores.contains("azul") + " " + colores.size());

        // Objetos propios: gracias a equals y hashCode no se duplican
        Set<Coche> garaje = new HashSet<>();
        garaje.add(new Coche("1234ABC"));
        garaje.add(new Coche("1234ABC"));
        System.out.println("Coches distintos: " + garaje.size()); // 1

        // Operaciones de conjuntos (sobre copias)
        Set<Integer> a = new TreeSet<>(List.of(1, 2, 3, 4));
        Set<Integer> b = new TreeSet<>(List.of(3, 4, 5));
        Set<Integer> union = new TreeSet<>(a);
        union.addAll(b);
        Set<Integer> interseccion = new TreeSet<>(a);
        interseccion.retainAll(b);
        Set<Integer> diferencia = new TreeSet<>(a);
        diferencia.removeAll(b);
        System.out.println(union + " " + interseccion + " " + diferencia); // [1, 2, 3, 4, 5] [3, 4] [1, 2]
    }
}

