import java.util.*;

public class Comparar {
    public static void main(String[] args) {
        List<Alumno> clase = new ArrayList<>(List.of(
            new Alumno("Marta", 8.5),
            new Alumno("Ana", 6.0),
            new Alumno("Luis", 8.5)
        ));

        // Orden natural (Comparable): por nombre
        Collections.sort(clase);
        System.out.println(clase);

        // Otro orden con Comparator: por nota descendente y, si empatan, por nombre
        clase.sort(Comparator.comparingDouble(Alumno::getNota).reversed()
                .thenComparing(Alumno::getNombre));
        System.out.println(clase);

        // Comparator con lambda: por longitud del nombre
        clase.sort((x, y) -> Integer.compare(x.getNombre().length(), y.getNombre().length()));
        System.out.println(clase);

        // TreeSet usa la comparación: si da 0, lo considera duplicado
        Set<Alumno> porNota = new TreeSet<>(Comparator.comparingDouble(Alumno::getNota));
        porNota.addAll(clase);
        System.out.println(porNota.size()); // 2: Marta y Luis tienen la misma nota
    }
}

class Alumno implements Comparable<Alumno> {
    private final String nombre;
    private final double nota;

    Alumno(String nombre, double nota) {
        this.nombre = nombre;
        this.nota = nota;
    }

    String getNombre() { return nombre; }
    double getNota() { return nota; }

    // Negativo: this va antes; 0: equivalentes; positivo: this va después
    @Override
    public int compareTo(Alumno otro) {
        return nombre.compareTo(otro.nombre);
    }

    @Override
    public String toString() {
        return nombre + "(" + nota + ")";
    }
}

import java.util.*;

public class EjemploMap {
    public static void main(String[] args) {
        Map<String, String> capitales = new HashMap<>();
        capitales.put("España", "Madrid");
        capitales.put("Francia", "París");
        capitales.put("Italia", "Roma");

        System.out.println(capitales.get("Francia"));                 // París
        System.out.println(capitales.get("Japón"));                   // null
        System.out.println(capitales.getOrDefault("Japón", "¿?"));    // ¿?
        System.out.println(capitales.containsKey("Italia"));          // true
        capitales.remove("Italia");

        // Recorrer clave y valor a la vez
        for (Map.Entry<String, String> e : capitales.entrySet()) {
            System.out.println(e.getKey() + " -> " + e.getValue());
        }

        // Contar apariciones de cada palabra (TreeMap: claves ordenadas)
        String texto = "el perro y el gato y el ratón";
        Map<String, Integer> cuenta = new TreeMap<>();
        for (String palabra : texto.split(" ")) {
            cuenta.merge(palabra, 1, Integer::sum);
        }
        System.out.println(cuenta); // {el=3, gato=1, perro=1, ratón=1, y=2}
    }
}

import java.util.*;

public class ColasYPilas {
    public static void main(String[] args) {
        // Cola FIFO
        Queue<String> cola = new ArrayDeque<>();
        cola.offer("Ana");
        cola.offer("Luis");
        cola.offer("Marta");
        System.out.println("Siguiente: " + cola.peek());   // mira sin sacar
        while (!cola.isEmpty()) {
            System.out.println("Atendiendo a " + cola.poll());
        }
        System.out.println(cola.poll());                   // null: cola vacía

        // Deque: añadir y sacar por ambos extremos
        Deque<Integer> doble = new ArrayDeque<>();
        doble.offerFirst(2);
        doble.offerFirst(1);
        doble.offerLast(3);
        System.out.println(doble);                         // [1, 2, 3]
        System.out.println(doble.pollLast() + " " + doble.pollFirst()); // 3 1

        // Deque como pila (LIFO)
        Deque<String> historial = new ArrayDeque<>();
        historial.push("página 1");
        historial.push("página 2");
        historial.push("página 3");
        System.out.println("Atrás: " + historial.pop());   // página 3

        // Cola de prioridad: aquí sale primero el mayor
        Queue<Integer> prioridad = new PriorityQueue<>(Comparator.reverseOrder());
        prioridad.addAll(List.of(5, 1, 9, 3));
        System.out.println(prioridad.poll());              // 9
    }
}

