import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.Scanner;

public class LeerEscribirTexto {
    public static void main(String[] args) {
        // Escribir con FileWriter (sobrescribe el fichero si existe)
        try (FileWriter fw = new FileWriter("saludo.txt", StandardCharsets.UTF_8)) {
            fw.write("Hola\n");
            fw.write("Adiós\n");
        } catch (IOException e) {
            System.out.println("Error al escribir: " + e.getMessage());
        }

        // Leer carácter a carácter con FileReader
        try (FileReader fr = new FileReader("saludo.txt", StandardCharsets.UTF_8)) {
            int c;
            while ((c = fr.read()) != -1) {     // -1 indica fin de fichero
                System.out.print((char) c);
            }
        } catch (IOException e) {
            System.out.println("Error al leer: " + e.getMessage());
        }

        // PrintWriter: println y printf como en System.out
        try (PrintWriter pw = new PrintWriter("numeros.txt", StandardCharsets.UTF_8)) {
            for (int i = 1; i <= 5; i++) {
                pw.println(i * i);
            }
        } catch (IOException e) {
            System.out.println("Error: " + e.getMessage());
        }

        // Scanner sobre un fichero: leer números
        int suma = 0;
        try (Scanner sc = new Scanner(new File("numeros.txt"), StandardCharsets.UTF_8)) {
            while (sc.hasNextInt()) {
                suma += sc.nextInt();
            }
        } catch (IOException e) {
            System.out.println("Error: " + e.getMessage());
        }
        System.out.println("Suma: " + suma); // 55
    }
}

import java.io.*;

public class Buffers {
    public static void main(String[] args) {
        // Escribir con buffer
        try (BufferedWriter bw = new BufferedWriter(new FileWriter("lineas.txt"))) {
            for (int i = 1; i <= 1000; i++) {
                bw.write("Línea " + i);
                bw.newLine();                 // salto de línea del sistema
            }
        } catch (IOException e) {
            System.out.println("Error al escribir: " + e.getMessage());
        }

        // Leer línea a línea con buffer
        int contador = 0;
        try (BufferedReader br = new BufferedReader(new FileReader("lineas.txt"))) {
            String linea;
            while ((linea = br.readLine()) != null) {   // null indica fin de fichero
                if (linea.endsWith("00")) {
                    System.out.println(linea);
                }
                contador++;
            }
        } catch (IOException e) {
            System.out.println("Error al leer: " + e.getMessage());
        }
        System.out.println("Leídas " + contador + " líneas");

        // Comparar: 100 000 escrituras de un byte sin buffer y con buffer
        long t0 = System.nanoTime();
        try (FileOutputStream sin = new FileOutputStream("sinBuffer.bin")) {
            for (int i = 0; i < 100_000; i++) {
                sin.write('x');               // cada byte es una escritura en disco
            }
        } catch (IOException e) {
            System.out.println(e.getMessage());
        }
        long t1 = System.nanoTime();
        try (BufferedOutputStream con = new BufferedOutputStream(new FileOutputStream("conBuffer.bin"))) {
            for (int i = 0; i < 100_000; i++) {
                con.write('x');               // se acumula y se escribe en bloques
            }
        } catch (IOException e) {
            System.out.println(e.getMessage());
        }
        long t2 = System.nanoTime();
        System.out.printf("Sin buffer: %d ms · Con buffer: %d ms%n", (t1 - t0) / 1_000_000, (t2 - t1) / 1_000_000);
    }
}

import java.io.*;

public class ArchivosBinarios {
    public static void main(String[] args) {
        String ruta = "alumnos.bin";

        // Escribir: cada tipo ocupa siempre lo mismo (int 4 bytes, double 8...)
        try (DataOutputStream out = new DataOutputStream(new FileOutputStream(ruta))) {
            out.writeUTF("Ana");
            out.writeInt(17);
            out.writeDouble(8.75);
            out.writeUTF("Luis");
            out.writeInt(18);
            out.writeDouble(6.5);
            System.out.println("Bytes escritos: " + out.size());
        } catch (IOException e) {
            System.out.println("Error al escribir: " + e.getMessage());
        }

        // Leer: en el MISMO orden y con los mismos tipos con que se escribió
        try (DataInputStream in = new DataInputStream(new FileInputStream(ruta))) {
            while (true) {
                String nombre = in.readUTF();
                int edad = in.readInt();
                double nota = in.readDouble();
                System.out.println(nombre + ", " + edad + " años, nota " + nota);
            }
        } catch (EOFException e) {
            System.out.println("Fin del fichero");
        } catch (IOException e) {
            System.out.println("Error al leer: " + e.getMessage());
        }
    }
}

import java.io.IOException;
import java.io.RandomAccessFile;

public class AccesoAleatorio {
    public static void main(String[] args) {
        final int TAM_INT = 4; // un int ocupa 4 bytes

        try (RandomAccessFile raf = new RandomAccessFile("numeros.bin", "rw")) {
            raf.setLength(0);                 // vaciamos el fichero
            for (int i = 0; i < 10; i++) {
                raf.writeInt(i * 10);         // 0, 10, 20, ... 90
            }
            System.out.println("Tamaño: " + raf.length() + " bytes");          // 40

            // Saltar directamente al sexto número (índice 5)
            raf.seek(5 * TAM_INT);
            System.out.println("Índice 5: " + raf.readInt());                 // 50
            System.out.println("Puntero en el byte " + raf.getFilePointer()); // 24

            // Sobrescribir el tercer número sin tocar el resto
            raf.seek(2 * TAM_INT);
            raf.writeInt(-1);

            // Leer todo desde el principio
            raf.seek(0);
            while (raf.getFilePointer() < raf.length()) {
                System.out.print(raf.readInt() + " ");
            }
            System.out.println();
        } catch (IOException e) {
            System.out.println("Error: " + e.getMessage());
        }
    }
}

import java.io.*;
import java.util.ArrayList;
import java.util.List;

public class Serializacion {
    public static void main(String[] args) {
        Equipo equipo = new Equipo("Los Búhos");
        equipo.fichar(new Jugador("Ana", 10, "1234"));
        equipo.fichar(new Jugador("Luis", 7, "abcd"));

        // Serializar: objeto -> bytes en un fichero
        try (ObjectOutputStream out = new ObjectOutputStream(new FileOutputStream("equipo.dat"))) {
            out.writeObject(equipo);
        } catch (IOException e) {
            System.out.println("Error al guardar: " + e.getMessage());
        }

        // Deserializar: bytes -> objeto (hay que hacer casting)
        try (ObjectInputStream in = new ObjectInputStream(new FileInputStream("equipo.dat"))) {
            Equipo leido = (Equipo) in.readObject();
            System.out.println(leido);   // Los Búhos [Ana#10 pin=null, Luis#7 pin=null]
        } catch (IOException | ClassNotFoundException e) {
            System.out.println("Error al leer: " + e.getMessage());
        }
    }
}

class Equipo implements Serializable {
    private static final long serialVersionUID = 1L;
    private final String nombre;
    private final List<Jugador> jugadores = new ArrayList<>(); // Jugador también debe ser Serializable

    Equipo(String nombre) { this.nombre = nombre; }
    void fichar(Jugador j) { jugadores.add(j); }

    @Override
    public String toString() { return nombre + " " + jugadores; }
}

class Jugador implements Serializable {
    private static final long serialVersionUID = 1L;
    private final String nombre;
    private final int dorsal;
    private transient String pin;   // transient: no se guarda

    Jugador(String nombre, int dorsal, String pin) {
        this.nombre = nombre;
        this.dorsal = dorsal;
        this.pin = pin;
    }

    @Override
    public String toString() { return nombre + "#" + dorsal + " pin=" + pin; }
}

