public class Layouts {
    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> {
            JFrame f = new JFrame("Calculadora (layouts combinados)");
            f.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);

            // BorderLayout (el de JFrame por defecto): 5 zonas
            f.setLayout(new BorderLayout(5, 5));
            JTextField pantalla = new JTextField("0");
            pantalla.setHorizontalAlignment(JTextField.RIGHT);
            f.add(pantalla, BorderLayout.NORTH);

            // GridLayout: rejilla de celdas iguales (4 filas x 4 columnas)
            JPanel teclado = new JPanel(new GridLayout(4, 4, 3, 3));
            for (String t : "7 8 9 / 4 5 6 * 1 2 3 - 0 . = +".split(" ")) {
                teclado.add(new JButton(t));
            }
            f.add(teclado, BorderLayout.CENTER);

            // FlowLayout (el de JPanel por defecto): en fila, aquí alineado a la derecha
            JPanel inferior = new JPanel(new FlowLayout(FlowLayout.RIGHT));
            inferior.add(new JButton("C"));
            inferior.add(new JButton("Salir"));
            f.add(inferior, BorderLayout.SOUTH);

            f.pack();                       // ajusta el tamaño al contenido
            f.setLocationRelativeTo(null);
            f.setVisible(true);
        });
    }
}

