import javax.swing.*;
import java.awt.*;
import java.awt.event.*;

public class Eventos {
    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> {
            JFrame f = new JFrame("Eventos");
            f.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
            f.setLayout(new FlowLayout());

            JButton sumar = new JButton("Sumar");
            JLabel contador = new JLabel("0");
            JTextField campo = new JTextField(10);
            JLabel estado = new JLabel("Pasa el ratón por el botón");

            // 1. Con una lambda (ActionListener solo tiene un método)
            sumar.addActionListener(e -> {
                int valor = Integer.parseInt(contador.getText()) + 1;
                contador.setText(String.valueOf(valor));
            });

            // 2. Con una clase anónima
            campo.addActionListener(new ActionListener() {
                @Override
                public void actionPerformed(ActionEvent e) {   // se dispara al pulsar Enter
                    estado.setText("Has escrito: " + campo.getText());
                }
            });

            // 3. Con una clase propia que recibe el componente que necesita
            sumar.addActionListener(new Registro(estado));

            // Ratón: MouseAdapter evita implementar todos los métodos de MouseListener
            sumar.addMouseListener(new MouseAdapter() {
                @Override
                public void mouseEntered(MouseEvent e) { estado.setText("Ratón encima"); }

                @Override
                public void mouseExited(MouseEvent e) { estado.setText("Ratón fuera"); }
            });

            // Teclado: el componente debe tener el foco
            campo.addKeyListener(new KeyAdapter() {
                @Override
                public void keyReleased(KeyEvent e) {
                    f.setTitle("Última tecla: " + KeyEvent.getKeyText(e.getKeyCode()));
                }
            });

            f.add(sumar);
            f.add(contador);
            f.add(campo);
            f.add(estado);
            f.setSize(420, 150);
            f.setVisible(true);
        });
    }
}

class Registro implements ActionListener {
    private final JLabel destino;

    Registro(JLabel destino) {
        this.destino = destino;
    }

    @Override
    public void actionPerformed(ActionEvent e) {
        destino.setText("Pulsado: " + e.getActionCommand());
    }
}

import javax.swing.*;
import java.awt.event.*;
import java.io.File;

public class Dialogos {
    public static void main(String[] args) {
        SwingUtilities.invokeLater(Dialogos::crear);
    }

    static void crear() {
        JFrame f = new JFrame("Diálogos");
        f.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        f.setSize(400, 250);
        JPanel panel = new JPanel();
        JButton abrir = new JButton("Abrir archivo…");
        panel.add(abrir);
        panel.add(new JLabel("Clic derecho para el menú contextual"));
        f.add(panel);
        f.setVisible(true);

        // Mensajes: el primer parámetro es la ventana sobre la que se centran
        JOptionPane.showMessageDialog(f, "Bienvenido");
        JOptionPane.showMessageDialog(f, "Algo ha fallado", "Error", JOptionPane.ERROR_MESSAGE);

        // Confirmación
        int r = JOptionPane.showConfirmDialog(f, "¿Guardar los cambios?");
        if (r == JOptionPane.YES_OPTION) {
            System.out.println("Guardando…");
        }

        // Pedir un texto (null si se cancela)
        String nombre = JOptionPane.showInputDialog(f, "¿Cómo te llamas?");
        if (nombre != null && !nombre.isBlank()) {
            System.out.println("Hola, " + nombre);
        }

        // Botones personalizados: devuelve el índice pulsado (-1 si se cierra)
        String[] opciones = {"Fácil", "Normal", "Difícil"};
        int elegida = JOptionPane.showOptionDialog(f, "Elige dificultad", "Nueva partida",
                JOptionPane.DEFAULT_OPTION, JOptionPane.QUESTION_MESSAGE, null, opciones, opciones[1]);
        if (elegida >= 0) {
            System.out.println("Dificultad: " + opciones[elegida]);
        }

        // Selector de archivos
        abrir.addActionListener(e -> {
            JFileChooser selector = new JFileChooser();
            if (selector.showOpenDialog(f) == JFileChooser.APPROVE_OPTION) {
                File elegido = selector.getSelectedFile();
                JOptionPane.showMessageDialog(f, "Has elegido " + elegido.getName());
            }
        });

        // Menú contextual (clic derecho)
        JPopupMenu menu = new JPopupMenu();
        JMenuItem copiar = new JMenuItem("Copiar");
        copiar.addActionListener(e -> System.out.println("Copiar"));
        menu.add(copiar);
        menu.add(new JMenuItem("Pegar"));
        panel.addMouseListener(new MouseAdapter() {
            @Override public void mousePressed(MouseEvent e) { mostrar(e); }
            @Override public void mouseReleased(MouseEvent e) { mostrar(e); }

            private void mostrar(MouseEvent e) {
                if (e.isPopupTrigger()) {   // según el sistema, al pulsar o al soltar
                    menu.show(e.getComponent(), e.getX(), e.getY());
                }
            }
        });
    }
}

import javax.swing.*;
import java.awt.*;
import java.time.LocalTime;
import java.time.format.DateTimeFormatter;

public class Graficos {
    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> {
            JFrame f = new JFrame("Reloj");
            f.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
            Reloj reloj = new Reloj();
            f.add(reloj);
            f.setSize(320, 220);
            f.setVisible(true);

            // javax.swing.Timer: ejecuta la acción cada 1000 ms en el hilo de Swing
            new Timer(1000, e -> reloj.repaint()).start();
        });
    }
