class Reloj extends JPanel {
    private static final DateTimeFormatter FORMATO = DateTimeFormatter.ofPattern("HH:mm:ss");

    @Override
    protected void paintComponent(Graphics g) {
        super.paintComponent(g);                  // limpia el fondo
        Graphics2D g2 = (Graphics2D) g;
        g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

        LocalTime ahora = LocalTime.now();
        int ancho = getWidth() - 40;

        // Barra que se llena con los segundos
        g2.setColor(new Color(255, 111, 30));
        g2.fillRect(20, 120, ancho * ahora.getSecond() / 59, 20);
        g2.setColor(Color.DARK_GRAY);
        g2.drawRect(20, 120, ancho, 20);

        g2.setFont(new Font("SansSerif", Font.BOLD, 36));
        g2.drawString(ahora.format(FORMATO), 70, 90);
    }
}

import java.sql.Connection;
import java.sql.DatabaseMetaData;
import java.sql.DriverManager;
import java.sql.SQLException;

public class Conexion {
    // URL: jdbc:<gestor>://<servidor>:<puerto>/<base de datos>
    private static final String URL = "jdbc:mysql://localhost:3306/tienda";
    private static final String USUARIO = "root";
    private static final String PASSWORD = "";

    public static void main(String[] args) {
        // try-with-resources cierra la conexión automáticamente
        try (Connection conexion = DriverManager.getConnection(URL, USUARIO, PASSWORD)) {
            DatabaseMetaData info = conexion.getMetaData();
            System.out.println("Conectado a " + info.getDatabaseProductName()
                    + " " + info.getDatabaseProductVersion());
        } catch (SQLException e) {
            // Causas típicas: servidor parado, base de datos inexistente,
            // usuario o contraseña incorrectos, o falta el driver en el proyecto
            System.out.println("Error de conexión: " + e.getMessage());
        }
    }
}

import java.sql.*;

public class ConsultarProductos {
    private static final String URL = "jdbc:mysql://localhost:3306/tienda";

    public static void main(String[] args) {
        double precioMaximo = 200;
        String sql = "SELECT nombre, precio FROM producto WHERE precio <= ? ORDER BY precio";

        try (Connection con = DriverManager.getConnection(URL, "root", "");
             PreparedStatement ps = con.prepareStatement(sql)) {

            ps.setDouble(1, precioMaximo);           // el primer ? es el 1

            try (ResultSet rs = ps.executeQuery()) {
                // next() avanza a la siguiente fila; devuelve false cuando no quedan
                while (rs.next()) {
                    String nombre = rs.getString("nombre");
                    double precio = rs.getDouble("precio");
                    System.out.printf("%-30s %8.2f €%n", nombre, precio);
                }
            }
        } catch (SQLException e) {
            System.out.println("Error en la consulta: " + e.getMessage());
        }
    }
}

import java.sql.*;

public class ModificarProductos {
    private static final String URL = "jdbc:mysql://localhost:3306/tienda";

    public static void main(String[] args) {
        try (Connection con = DriverManager.getConnection(URL, "root", "")) {

            // INSERT
            String insertar = "INSERT INTO producto (nombre, precio, codigo_fabricante) VALUES (?, ?, ?)";
            try (PreparedStatement ps = con.prepareStatement(insertar)) {
                ps.setString(1, "Ratón inalámbrico");
                ps.setDouble(2, 19.99);
                ps.setInt(3, 1);
                System.out.println("Insertadas: " + ps.executeUpdate());
            }

            // UPDATE: executeUpdate devuelve cuántas filas se han modificado
            String actualizar = "UPDATE producto SET precio = ? WHERE nombre = ?";
            try (PreparedStatement ps = con.prepareStatement(actualizar)) {
                ps.setDouble(1, 17.50);
                ps.setString(2, "Ratón inalámbrico");
                System.out.println("Actualizadas: " + ps.executeUpdate());
            }

            // DELETE dentro de una transacción: o se hace todo o nada
            con.setAutoCommit(false);
            try (PreparedStatement ps = con.prepareStatement("DELETE FROM producto WHERE nombre = ?")) {
                ps.setString(1, "Ratón inalámbrico");
                int borradas = ps.executeUpdate();
                if (borradas == 1) {
                    con.commit();
                    System.out.println("Borrado confirmado");
                } else {
                    con.rollback();
                    System.out.println("Se esperaba 1 fila y se han borrado " + borradas + ": deshecho");
                }
            } finally {
                con.setAutoCommit(true);
            }
        } catch (SQLException e) {
            System.out.println("Error: " + e.getMessage());
        }
    }
}
